            ; ds_select: replaces ir_cmd_to_key's entry (0x5D10). Raw NEC command 0x6A -> internal key in R7.
            ; RAM: g_ir_cmd 0x6A, g_input 0x47, g_power_on 0x4F, g_ui_page 0x45, g_osd_timer 0x27:0x28, g_ir_key2 0x6F
ds_select:
  DA89: e5 6a                    mov A,0x6A                  ; raw NEC command byte
  DA8B: c3                       clr C
  DA8C: 94 10                    subb A,#0x10              ; A = cmd - 0x10 ; C=1 if cmd < 0x10
  DA8E: 40 28                    jc ds_stock                 ; below range -> stock path
  DA90: b4 06 00                 cjne A,#6,ds_c1            ; never branches; sets C=1 if A < 6
ds_c1:
  DA93: 50 23                    jnc ds_stock                ; A >= 6 (cmd > 0x15) -> stock path
  DA95: ff                       mov R7,A                    ; R7 = index 0..5
  DA96: e5 4f                    mov A,0x4F                  ; g_power_on
  DA98: 60 18                    jz ds_eat                   ; standby -> ignore
  DA9A: e5 45                    mov A,0x45                  ; g_ui_page
  DA9C: 64 01                    xrl A,#1                    ; zero iff page == 1 (home)
  DA9E: 70 12                    jnz ds_eat                  ; in a menu -> ignore
  DAA0: ef                       mov A,R7
  DAA1: 04                       inc A                       ; input number 1..6
  DAA2: b5 47 02                 cjne A,0x47,ds_apply        ; not the current input -> switch
  DAA5: 80 0b                    sjmp ds_eat                 ; already selected -> ignore (no re-init, no OSD)
ds_apply:
  DAA7: f5 47                    mov 0x47,A                  ; g_input = target
  DAA9: 75 27 00                 mov 0x27,#0x00              ; g_osd_timer: show the input name, as a real press does
  DAAC: 75 28 c8                 mov 0x28,#0xC8
  DAAF: 12 56 40                 lcall 0x5640                ; input_apply: switch hardware + refresh display
ds_eat:
  DAB2: 7f ff                    mov R7,#0xFF                ; return "no key" to read_key
  DAB4: e4                       clr A
  DAB5: f5 6f                    mov 0x6F,A                  ; g_ir_key2: stock side effect of ir_cmd_to_key
  DAB7: 22                       ret
ds_stock:
  DAB8: e5 6a                    mov A,0x6A                  ; replay the displaced stock instructions
  DABA: b4 0f 00                 cjne A,#15,ds_c2            ; never branches; sets C=1 if cmd < 15
ds_c2:
  DABD: 50 f3                    jnc ds_eat                  ; cmd >= 15: not in the table -> "no key" (stock read erased flash)
  DABF: 90 93 98                 mov DPTR,#0x9398            ; ir_cmd_to_key_table
  DAC2: 93                       movc A,@A+DPTR              ; A = table[cmd]
  DAC3: 02 5d 17                 ljmp 0x5D17                 ; ir_cmd_to_key's tail: mov R7,A ; clr A ; mov 0x6F,A ; ret
            ; fx_auto_off: replaces post_power_on's tail `ljmp ui_clear_screen` (0x55B9). With Dimmer on
            ; Auto OFF, arm the screen-off countdown as a key press would, then take the stock tail call.
            ; Arming before the jump keeps the stack depth as stock; the countdown is only read by the
            ; main loop (0x33DB), so the order against ui_clear_screen does not matter.
fx_auto_off:
  DAC6: e5 29                    mov A,0x29                  ; g_dimmer_mode: 1 Always ON, 2 Auto OFF
  DAC8: b4 02 06                 cjne A,#0x02,fx_ao_done
  DACB: 75 2f 01                 mov 0x2F,#0x01            ; g_screen_off_hi
  DACE: 75 30 f4                 mov 0x30,#0xF4            ; g_screen_off_lo
fx_ao_done:
  DAD1: 02 5d 42                 ljmp 0x5D42                 ; ui_clear_screen, the stock tail call
            ; sv_limit: replaces post_power_on's `lcall audio_chips_init` (0x5596). Cold power-up and the
            ; wake from standby both come through here with the outputs muted, before the first volume
            ; write (volume_apply at 0x510A). Cap g_volume (speakers) and g_volume_hp (headphones) at
            ; their limits, whichever output is active, then go on into audio_chips_init, which returns
            ; to 0x5599: the stack depth is as stock. The capped value is what stock then shows, applies
            ; and saves; the volume keys are not touched.
sv_limit:
  DAD4: 74 19                    mov A,#0x19               ; g_volume, speakers limit 25
  DAD6: c3                       clr C
  DAD7: 95 31                    subb A,0x31               ; limit - volume
  DAD9: 50 03                    jnc sv_hp                      ; volume <= limit: keep it
  DADB: 75 31 19                 mov 0x31,#0x19
sv_hp:
  DADE: 74 14                    mov A,#0x14               ; g_volume_hp, headphones limit 20
  DAE0: c3                       clr C
  DAE1: 95 52                    subb A,0x52               ; limit - volume
  DAE3: 50 03                    jnc sv_go                      ; volume <= limit: keep it
  DAE5: 75 52 14                 mov 0x52,#0x14
sv_go:
  DAE8: 02 50 d1                 ljmp 0x50D1                 ; audio_chips_init
            ; vp_apply: replaces vol_key_tail's `lcall volume_apply` (0x0F4A; R7 = g_volume), the one write
            ; of the volume to the NJW1194 that all four volume keys share. On Optical and Coaxial without
            ; lock the chip keeps its mute code; on any other input, and with lock, this is volume_apply.
            ; Skipping the write also raises the re-mute request with its 1 s countdown, as Timer0 does when
            ; it sees no lock (t0_remute_no_lock, 0x3EA4). The head and Timer0 sample P4.2 on their own: if
            ; only this test saw it high, the volume would stay unwritten. With the request up, the main
            ; loop mutes and the unmute that follows writes the volume from RAM.
vp_apply:
  DAEB: e5 47                    mov A,0x47                  ; g_input
  DAED: 24 fe                    add A,#0xFE                 ; input - 2
  DAEF: 60 03                    jz vp_digital               ; 2 Optical
  DAF1: 14                       dec A
  DAF2: 70 0c                    jnz vp_go                   ; not 3 Coaxial either
vp_digital:
  DAF4: 30 c2 09                 jnb 0xC2,vp_go              ; P4.2 low: lock
  DAF7: d2 0c                    setb 0x0C                   ; 0x21.4: re-mute request, served by main_tick_tasks
  DAF9: 75 43 00                 mov 0x43,#0x00              ; g_mute_timer = 100 ticks
  DAFC: 75 44 64                 mov 0x44,#0x64
  DAFF: 22                       ret                         ; no signal: the number changes, the chip does not
vp_go:
  DB00: 02 4d dc                 ljmp 0x4DDC                 ; volume_apply, returns to the tail
            ; mi_switch: replaces input_menu_select's `lcall audio_apply_mute` (0x5892), reached with 0x22.4
            ; cleared and the settings save armed, as input_apply is at 0x5645. Do what input_step and
            ; input_apply do for the Source key: mute, format poll in 10 ticks, unmute countdown 200 ticks,
            ; input_set_hw. Then rejoin input_menu_select at 0x589D, past its `clr P4.0` and the re-init
            ; countdown (0x5895..0x589C, no longer reached): page, refresh countdown, clear, list state.
            ; A jump in and a jump back, so the stack is as deep as in stock when input_set_hw runs, one
            ; call below the key handler, as on the Source key's path.
mi_switch:
  DB03: 12 58 d3                 lcall 0x58D3                ; audio_apply_mute: NJW1194 mute code, DAC mute
  DB06: 75 4b 00                 mov 0x4B,#0x00            ; g_format_poll: 10 ticks
  DB09: 75 4c 0a                 mov 0x4C,#0x0A
  DB0C: 75 43 00                 mov 0x43,#0x00            ; g_mute_timer: 200 ticks, then mute_timer_expired unmutes
  DB0F: 75 44 c8                 mov 0x44,#0xC8
  DB12: af 47                    mov R7,0x47                 ; g_input
  DB14: 12 24 d6                 lcall 0x24D6                ; input_set_hw: NJW1194 selector, muxes, receiver, DAC clocking
  DB17: 02 58 9d                 ljmp 0x589D                 ; input_menu_select's tail

